Rules.InvariantScript:
With(
    {
        nextEvent: First(
            Sort(
                Filter(
                    colECCSCutoverSchedule,
                    StartDate >= Today()
                ),
                StartDate,
                SortOrder.Ascending
            )
        )
    },
    If(
        IsBlank(nextEvent.StartDate),
        "No milestone scheduled",
        nextEvent.EventName &
        " | " &
        Text(
            nextEvent.StartDate,
            "[$-en-US]mmmm d, yyyy"
        )
    )
)

Set(
    gblSelectedWaveNumber,
    First(
        Split(
            drpWaveSubwaveFilter2.Selected.Value,
            " - "
        )
    ).Value
);
Set(
    gblSelectedSubWaveCode,
    Last(
        Split(
            drpWaveSubwaveFilter2.Selected.Value,
            " - "
        )
    ).Value
);
ClearCollect(
    colReadinessFacilities,
    Filter(
        'dim.Ref.Organizations',
        'Wave Number' = gblSelectedWaveNumber &&
        'SubWave2 Code' = gblSelectedSubWaveCode
    )
);
ClearCollect(
    colRegReadiness,

    {
        WorksheetName: "Accommodations",
        TotalRecords: CountRows(Filter('Accommodation Data Clone', IsBlank(gblSelectedWaveNumber) || FacilityMnem_Source in colReadinessFacilities.'Facility Mnemonic')),
        NoMatchRecords: CountRows(Filter('Accommodation Data Clone', (IsBlank(gblSelectedWaveNumber) || FacilityMnem_Source in colReadinessFacilities.'Facility Mnemonic') && TargetMatchMtx = "NO MATCH")),
        TestRecords: CountRows(Filter('Accommodation Data Clone', (IsBlank(gblSelectedWaveNumber) || FacilityMnem_Source in colReadinessFacilities.'Facility Mnemonic') && StartsWith(TargetMatchMtx, "TEST"))),
        ZconRecords: CountRows(Filter('Accommodation Data Clone', (IsBlank(gblSelectedWaveNumber) || FacilityMnem_Source in colReadinessFacilities.'Facility Mnemonic') && StartsWith(TargetMatchMtx, "ZCON"))),
        LiveRecords: CountRows(Filter('Accommodation Data Clone', (IsBlank(gblSelectedWaveNumber) || FacilityMnem_Source in colReadinessFacilities.'Facility Mnemonic') && StartsWith(TargetMatchMtx, "LIVE")))
    },

    {
        WorksheetName: "Locations",
        TotalRecords: CountRows(Filter(Locations, IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic')),
        NoMatchRecords: CountRows(Filter(Locations, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && 'Target Match Matrix' = "NO MATCH")),
        TestRecords: CountRows(Filter(Locations, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "TEST"))),
        ZconRecords: CountRows(Filter(Locations, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "ZCON"))),
        LiveRecords: CountRows(Filter(Locations, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "LIVE")))
    },

    {
        WorksheetName: "Services",
        TotalRecords: CountRows(Filter(Services, IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic')),
        NoMatchRecords: CountRows(Filter(Services, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && 'Target Match Matrix' = "NO MATCH")),
        TestRecords: CountRows(Filter(Services, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "TEST"))),
        ZconRecords: CountRows(Filter(Services, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "ZCON"))),
        LiveRecords: CountRows(Filter(Services, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "LIVE")))
    },

    {
        WorksheetName: "Insurance",
        TotalRecords: CountRows(Filter(Insurances, IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic')),
        NoMatchRecords: CountRows(Filter(Insurances, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && 'Target Match Matrix' = "NO MATCH")),
        TestRecords: CountRows(Filter(Insurances, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "TEST"))),
        ZconRecords: CountRows(Filter(Insurances, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "ZCON"))),
        LiveRecords: CountRows(Filter(Insurances, (IsBlank(gblSelectedWaveNumber) || 'Source Facility Mnemonic' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Matrix', "LIVE")))
    },

    {
        WorksheetName: "RoomBed",
        TotalRecords: CountRows(Filter('Room Beds', IsBlank(gblSelectedWaveNumber) || 'Source Facility Code' in colReadinessFacilities.'Facility Mnemonic')),
        NoMatchRecords: CountRows(Filter('Room Beds', (IsBlank(gblSelectedWaveNumber) || 'Source Facility Code' in colReadinessFacilities.'Facility Mnemonic') && 'Target Match Status' = "NO MATCH")),
        TestRecords: CountRows(Filter('Room Beds', (IsBlank(gblSelectedWaveNumber) || 'Source Facility Code' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Status', "TEST"))),
        ZconRecords: CountRows(Filter('Room Beds', (IsBlank(gblSelectedWaveNumber) || 'Source Facility Code' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Status', "ZCON"))),
        LiveRecords: CountRows(Filter('Room Beds', (IsBlank(gblSelectedWaveNumber) || 'Source Facility Code' in colReadinessFacilities.'Facility Mnemonic') && StartsWith('Target Match Status', "LIVE")))
    },

    {
        WorksheetName: "Discharge Disposition",
        TotalRecords: CountRows(Filter('Discharge Dispositions', IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic')),
        NoMatchRecords: CountRows(Filter('Discharge Dispositions', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && 'Target Match Matrix' = "NO MATCH")),
        TestRecords: CountRows(Filter('Discharge Dispositions', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "TEST"))),
        ZconRecords: CountRows(Filter('Discharge Dispositions', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "ZCON"))),
        LiveRecords: CountRows(Filter('Discharge Dispositions', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "LIVE")))
    },

    {
        WorksheetName: "Ins Auth Status",
        TotalRecords: CountRows(Filter('Insurance Auths', IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic')),
        NoMatchRecords: CountRows(Filter('Insurance Auths', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && 'Target Match Matrix Note' = "NO MATCH")),
        TestRecords: CountRows(Filter('Insurance Auths', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix Note', "TEST"))),
        ZconRecords: CountRows(Filter('Insurance Auths', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix Note', "ZCON"))),
        LiveRecords: CountRows(Filter('Insurance Auths', (IsBlank(gblSelectedWaveNumber) || 'Network Mnemonic Source' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix Note', "LIVE")))
    },

    {
        WorksheetName: "Financial Approver",
        TotalRecords: CountRows(Filter('Financial Approvers', IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic')),
        NoMatchRecords: CountRows(Filter('Financial Approvers', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && 'Target Match Matrix' = "NO MATCH")),
        TestRecords: CountRows(Filter('Financial Approvers', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "TEST"))),
        ZconRecords: CountRows(Filter('Financial Approvers', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "ZCON"))),
        LiveRecords: CountRows(Filter('Financial Approvers', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "LIVE")))
    },

    {
        WorksheetName: "Financial Class",
        TotalRecords: CountRows(Filter('Financial Classes', IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic')),
        NoMatchRecords: CountRows(Filter('Financial Classes', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && 'Target Match Matrix' = "NO MATCH")),
        TestRecords: CountRows(Filter('Financial Classes', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "TEST"))),
        ZconRecords: CountRows(Filter('Financial Classes', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "ZCON"))),
        LiveRecords: CountRows(Filter('Financial Classes', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Target Match Matrix', "LIVE")))
    },

    {
        WorksheetName: "Admit Source",
        TotalRecords: CountRows(Filter('Admit Source Mapping', IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic')),
        NoMatchRecords: CountRows(Filter('Admit Source Mapping', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && 'Match Status' = "NO MATCH")),
        TestRecords: CountRows(Filter('Admit Source Mapping', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Match Status', "TEST"))),
        ZconRecords: CountRows(Filter('Admit Source Mapping', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Match Status', "ZCON"))),
        LiveRecords: CountRows(Filter('Admit Source Mapping', (IsBlank(gblSelectedWaveNumber) || 'Source Network Mnemonic' in colReadinessFacilities.'Network Mnemonic') && StartsWith('Match Status', "LIVE")))
    }
);

With(
    {
        nextEvent: First(
            Sort(
                Filter(
                    colECCSCutoverSchedule,
                    StartDate >= Now()
                ),
                StartDate,
                SortOrder.Ascending
            )
        )
    },
    If(
        IsBlank(nextEvent.StartDate),
        "COUNTDOWN NOT CONFIGURED",
        With(
            {
                totalMinutes: DateDiff(
                    Now(),
                    nextEvent.StartDate,
                    TimeUnit.Minutes
                )
            },
            If(
                totalMinutes <= 0,
                "EVENT ACTIVE",
                Int(totalMinutes / 1440) &
                "d " &
                Mod(
                    Int(totalMinutes / 60),
                    24
                ) &
                "h " &
                Mod(
                    totalMinutes,
                    60
                ) &
                "m"
            )
        )
    )
)
